import{_ as r,o as n,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"Recherche: Die Klagsmaschine Dr. Michael Rami","description":"Dokumentation der systematischen Klagswellen gegen Privatpersonen und die Rolle des Michael Rami als juristischer Vollstrecker der Macht.","frontmatter":{"title":"Recherche: Die Klagsmaschine Dr. Michael Rami","description":"Dokumentation der systematischen Klagswellen gegen Privatpersonen und die Rolle des Michael Rami als juristischer Vollstrecker der Macht.","date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"recherche/klagsmaschine-michael-rami.md","filePath":"recherche/klagsmaschine-michael-rami.md"}'),t={name:"recherche/klagsmaschine-michael-rami.md"};function s(l,e,h,d,c,u){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="recherche-die-klagsmaschine-dr-michael-rami" tabindex="-1">Recherche: Die Klagsmaschine Dr. Michael Rami <a class="header-anchor" href="#recherche-die-klagsmaschine-dr-michael-rami" aria-label="Permalink to &quot;Recherche: Die Klagsmaschine Dr. Michael Rami&quot;">​</a></h1><p>In unserem Projekt untersuchen wir die Instrumentalisierung der Justiz zur Absicherung von Machtstrukturen. Der Fall Michael Rami ist hierfür das Paradebeispiel des 21. Jahrhunderts.</p><h2 id="das-geschaftsmodell-abmahnung-als-einschuchterung" tabindex="-1">Das Geschäftsmodell: Abmahnung als Einschüchterung <a class="header-anchor" href="#das-geschaftsmodell-abmahnung-als-einschuchterung" aria-label="Permalink to &quot;Das Geschäftsmodell: Abmahnung als Einschüchterung&quot;">​</a></h2><p>Michael Rami (Verfassungsrichter und Medienanwalt) hat im Auftrag von <strong>Katharina Nehammer</strong> eine Klagswelle losgetreten, die in Österreich beispiellos ist.</p><h3 id="_1-die-„4-500-euro-rechnung" tabindex="-1">1. Die „4.500-Euro-Rechnung“ <a class="header-anchor" href="#_1-die-„4-500-euro-rechnung" aria-label="Permalink to &quot;1. Die „4.500-Euro-Rechnung“&quot;">​</a></h3><p>Die Strategie ist simpel, aber vernichtend: Hunderte Privatpersonen erhalten standardisierte Abmahnungen.</p><ul><li><strong>Forderung:</strong> 3.500 Euro Entschädigung (für Katharina Nehammer) + ca. 940 Euro Anwaltskosten (für Rami).</li><li><strong>Grund:</strong> Das bloße Teilen eines Facebook-Postings (z.B. über die <em>Hygiene Austria</em>-Causa).</li><li><strong>Zielgruppe:</strong> Es traf gezielt <strong>Mindestpensionisten, Studenten und Geringverdiener</strong>. Viele zahlten aus purer Angst vor noch höheren Gerichtskosten.</li></ul><h3 id="_2-der-fall-des-61-jahrigen-karntners" tabindex="-1">2. Der Fall des 61-jährigen Kärntners <a class="header-anchor" href="#_2-der-fall-des-61-jahrigen-karntners" aria-label="Permalink to &quot;2. Der Fall des 61-jährigen Kärntners&quot;">​</a></h3><p>Ein dokumentierter Fall betraf einen Mann aus Klagenfurt, der lediglich ein kritisches Posting geteilt hatte. Rami zwang ihn zu einem teuren Vergleich und zum öffentlichen Widerruf. Kritiker bezeichnen dies als <strong>SLAPP</strong> (Strategic Lawsuit Against Public Participation) – eine Klage, die nur dazu dient, Kritiker finanziell zu ruinieren und mundtot zu machen.</p><h2 id="die-doppelrolle-des-„schurken" tabindex="-1">Die Doppelrolle des „Schurken“ <a class="header-anchor" href="#die-doppelrolle-des-„schurken" aria-label="Permalink to &quot;Die Doppelrolle des „Schurken“&quot;">​</a></h2><p>Was Rami als „System-Schurken“ für unser Projekt so wertvoll macht, ist seine Doppelfunktion:</p><ul><li><strong>Der Höchstrichter:</strong> Tagsüber entscheidet er über die Verfassungsmäßigkeit von Gesetzen am VfGH (nominiert von der FPÖ).</li><li><strong>Der Elite-Anwalt:</strong> Nachts nutzt er sein juristisches Gewicht, um die Kritiker der Kanzlerfamilie oder von FPÖ-Größen (wie Strache oder Kickl) niederzuklagen.</li></ul><h3 id="das-„scientific-washing-der-inseraten-affare" tabindex="-1">Das „Scientific Washing“ der Inseraten-Affäre <a class="header-anchor" href="#das-„scientific-washing-der-inseraten-affare" aria-label="Permalink to &quot;Das „Scientific Washing“ der Inseraten-Affäre&quot;">​</a></h3><p>Aktuell (April 2026) versucht Rami in der Inseraten-Affäre (Eva Dichand), durch eine <strong>WU-Studie</strong> zu beweisen, dass Korruption statistisch gar nicht stattgefunden habe. Es ist die Fortführung seiner Strategie: Wenn Chats zu erdrückend werden, schlägt er mit Gutachten und Klagen zurück.</p><h2 id="bedeutung-fur-das-horten-mysterium" tabindex="-1">Bedeutung für das Horten-Mysterium <a class="header-anchor" href="#bedeutung-fur-das-horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das Horten-Mysterium&quot;">​</a></h2><p>Rami ist das moderne Äquivalent zu den Juristen der Arisierung. Er verbrennt keine Akten, er erstickt die Wahrheit in einem Berg aus Klagsdrohungen und Gebührenordnungen.</p><p><em>Der Index der Macht steigt. Wir dokumentieren die Kosten der Wahrheit.</em></p><hr><p><em>Quellen: Kurier, Krone, Kleine Zeitung (Stand 07. April 2026), Gerichtsakten der Nehammer-Klagswelle.</em></p>',19)])])}const m=r(t,[["render",s]]);export{g as __pageData,m as default};
